CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TYPE event_type AS ENUM ('hackathon','buildathon','datathon','game_jam','ideathon','innovation_challenge','ai_challenge','data_science_competition','coding_competition','security_ctf','hardware_challenge','startup_challenge','open_innovation_challenge','designathon','quant_competition','robotics_competition','other');
CREATE TYPE event_status AS ENUM ('ANNOUNCED','REGISTRATION_UPCOMING','REGISTRATION_OPEN','REGISTRATION_CLOSED','UPCOMING','ONGOING','SUBMISSIONS_OPEN','JUDGING','RESULTS_PENDING','COMPLETED','CANCELLED','POSTPONED','UNKNOWN');
CREATE TYPE event_format AS ENUM ('ONLINE','IN_PERSON','HYBRID','UNKNOWN');
CREATE TYPE location_type AS ENUM ('ONLINE','VENUE','MULTI_VENUE','GLOBAL','UNKNOWN');
CREATE TYPE source_ingestion_mode AS ENUM ('API','RSS','SITEMAP','STATIC_HTML','BROWSER','SEARCH_DISCOVERY','MANUAL','PARTNER','DISCOVERY_ONLY','BLOCKED');
CREATE TYPE source_health AS ENUM ('HEALTHY','DEGRADED','BROKEN','BLOCKED','PERMISSION_REQUIRED','UNKNOWN');
CREATE TYPE review_state AS ENUM ('OPEN','IN_REVIEW','RESOLVED','DISMISSED');
CREATE TYPE conflict_severity AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE dedup_decision AS ENUM ('AUTO_MERGE','REVIEW','SEPARATE','MANUAL_MERGE','MANUAL_SEPARATE');
CREATE TYPE eligibility_result AS ENUM ('ELIGIBLE','INELIGIBLE','UNKNOWN');
CREATE TYPE user_event_state AS ENUM ('SAVED','INTERESTED','APPLYING','APPLIED','ACCEPTED','PARTICIPATING','SUBMITTED','COMPLETED','NOT_INTERESTED');
CREATE TYPE alert_channel AS ENUM ('IN_APP','EMAIL');
CREATE TYPE alert_delivery_status AS ENUM ('PENDING','SENT','FAILED','SKIPPED');
CREATE TYPE organization_role AS ENUM ('ORGANIZER','CO_ORGANIZER','HOST','SPONSOR','PARTNER','TECHNOLOGY_PARTNER','COMMUNITY_PARTNER','MEDIA_PARTNER','PRIZE_PARTNER','VENUE_PARTNER');
CREATE TYPE person_role AS ENUM ('JUDGE','MENTOR','SPEAKER','ORGANIZER','ADVISOR');
CREATE TYPE requirement_type AS ENUM ('TECHNOLOGY','API','DATASET','OPEN_SOURCE','VIDEO','PITCH_DECK','GITHUB','LIVE_DEMO','DOCUMENTATION','LICENSE','OTHER');
CREATE TYPE resource_type AS ENUM ('DATASET','API','SDK','CLOUD_CREDIT','DOCUMENTATION','STARTER_CODE','WORKSHOP','MENTORSHIP','OFFICE_HOURS','COMPUTE','HARDWARE','OTHER');
CREATE TYPE phase_type AS ENUM ('REGISTRATION','IDEA_SUBMISSION','QUALIFIER','PROTOTYPE','SEMIFINAL','FINAL','SUBMISSION','JUDGING','DEMO_DAY','RESULTS','OTHER');
CREATE TYPE extraction_method AS ENUM ('API','JSON_LD','EMBEDDED_JSON','DETERMINISTIC','LLM','MANUAL');
CREATE TYPE crawl_run_status AS ENUM ('RUNNING','SUCCEEDED','PARTIAL','FAILED','CANCELLED');
CREATE TYPE fetch_status AS ENUM ('PENDING','FETCHED','UNCHANGED','FAILED','SKIPPED','BLOCKED');
CREATE TYPE frontier_state AS ENUM ('DISCOVERED','QUEUED','FETCHING','FETCHED','FAILED','BLOCKED','EXHAUSTED');
CREATE TYPE auth_provider AS ENUM ('GOOGLE','GITHUB','EMAIL_MAGIC_LINK','OTHER');

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

CREATE TABLE event_series (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,normalized_name text NOT NULL,official_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_series_normalized_name_trgm_idx ON event_series USING gin (normalized_name gin_trgm_ops);
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),location_type location_type NOT NULL DEFAULT 'UNKNOWN',venue text,address text,district text,city text,state_region text,country text,country_code char(2),postal_code text,latitude numeric(9,6),longitude numeric(9,6),timezone text,normalized_key text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE INDEX locations_geo_lookup_idx ON locations (country_code,state_region,city);
CREATE INDEX locations_normalized_key_idx ON locations (normalized_key);
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,normalized_name text NOT NULL,organization_type text,website text,logo_url text,description text,country_code char(2),industry text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX organizations_name_trgm_idx ON organizations USING gin (normalized_name gin_trgm_ops);
CREATE INDEX organizations_country_idx ON organizations(country_code);
CREATE TABLE people (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,normalized_name text NOT NULL,title text,organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL,profile_url text,linkedin_url text,github_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX people_name_trgm_idx ON people USING gin (normalized_name gin_trgm_ops);
CREATE TABLE tracks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,normalized_name text NOT NULL UNIQUE,parent_id uuid REFERENCES tracks(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE technologies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,normalized_name text NOT NULL UNIQUE,category text,website text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE taxonomy_aliases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL CHECK (entity_type IN ('track','technology','organization','event_series')),entity_id uuid NOT NULL,alias citext NOT NULL,normalized_alias text NOT NULL,language_code varchar(12),source text,UNIQUE(entity_type,normalized_alias));
CREATE INDEX taxonomy_aliases_alias_trgm_idx ON taxonomy_aliases USING gin (normalized_alias gin_trgm_ops);

CREATE TABLE hackathons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,normalized_name text NOT NULL,subtitle text,short_description text,full_description text,event_type event_type NOT NULL DEFAULT 'hackathon',is_hackathon_like boolean NOT NULL DEFAULT true,status event_status NOT NULL DEFAULT 'UNKNOWN',format event_format NOT NULL DEFAULT 'UNKNOWN',event_series_id uuid REFERENCES event_series(id) ON DELETE SET NULL,edition_label text,edition_year smallint,primary_location_id uuid REFERENCES locations(id) ON DELETE SET NULL,eligible_worldwide boolean,is_free boolean,participation_fee numeric(14,2),participation_fee_currency char(3),registration_url text,application_url text,submission_url text,official_url text,announcement_at timestamptz,registration_open_at timestamptz,registration_close_at timestamptz,start_at timestamptz,end_at timestamptz,submission_open_at timestamptz,submission_close_at timestamptz,judging_start_at timestamptz,judging_end_at timestamptz,results_at timestamptz,original_timezone text,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),last_verified_at timestamptz,quality_score numeric(5,2),source_count integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,merged_into_id uuid REFERENCES hackathons(id) ON DELETE SET NULL,search_text tsvector GENERATED ALWAYS AS (setweight(to_tsvector('simple',coalesce(name,'')),'A')||setweight(to_tsvector('simple',coalesce(subtitle,'')),'B')||setweight(to_tsvector('simple',coalesce(short_description,'')),'C')||setweight(to_tsvector('simple',coalesce(full_description,'')),'D')) STORED,embedding vector(384),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK (quality_score IS NULL OR quality_score BETWEEN 0 AND 100),CHECK (participation_fee IS NULL OR participation_fee >= 0),CHECK (end_at IS NULL OR start_at IS NULL OR end_at >= start_at),CHECK (edition_year IS NULL OR edition_year BETWEEN 1900 AND 2200),CHECK (merged_into_id IS NULL OR merged_into_id <> id));
CREATE INDEX hackathons_active_status_dates_idx ON hackathons(is_active,status,registration_close_at,start_at);
CREATE INDEX hackathons_format_idx ON hackathons(format);
CREATE INDEX hackathons_series_idx ON hackathons(event_series_id,edition_year);
CREATE INDEX hackathons_location_idx ON hackathons(primary_location_id);
CREATE INDEX hackathons_name_trgm_idx ON hackathons USING gin (normalized_name gin_trgm_ops);
CREATE INDEX hackathons_search_text_idx ON hackathons USING gin(search_text);
CREATE INDEX hackathons_embedding_hnsw_idx ON hackathons USING hnsw (embedding vector_cosine_ops) WHERE embedding IS NOT NULL;
CREATE INDEX hackathons_last_verified_idx ON hackathons(last_verified_at) WHERE is_active;
CREATE TABLE hackathon_locations (hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,location_id uuid NOT NULL REFERENCES locations(id) ON DELETE CASCADE,is_primary boolean NOT NULL DEFAULT false,label text,PRIMARY KEY(hackathon_id,location_id));
CREATE TABLE hackathon_organizations (hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,role organization_role NOT NULL,sponsorship_tier text,source_label text,PRIMARY KEY(hackathon_id,organization_id,role));
CREATE INDEX hackathon_org_role_idx ON hackathon_organizations(role,organization_id);
CREATE TABLE event_people (hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,person_id uuid NOT NULL REFERENCES people(id) ON DELETE CASCADE,role person_role NOT NULL,sort_order integer,PRIMARY KEY(hackathon_id,person_id,role));
CREATE TABLE hackathon_tracks (hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,track_id uuid NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,declared boolean NOT NULL DEFAULT true,confidence numeric(5,4),method_version text,PRIMARY KEY(hackathon_id,track_id),CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1));
CREATE INDEX hackathon_tracks_track_idx ON hackathon_tracks(track_id,hackathon_id);
CREATE TABLE hackathon_technologies (hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,technology_id uuid NOT NULL REFERENCES technologies(id) ON DELETE CASCADE,role text,required boolean,recommended boolean,sponsor_technology boolean,declared boolean NOT NULL DEFAULT true,confidence numeric(5,4),method_version text,PRIMARY KEY(hackathon_id,technology_id,role),CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1));
CREATE INDEX hackathon_technologies_tech_idx ON hackathon_technologies(technology_id,hackathon_id);

CREATE TABLE eligibility_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL UNIQUE REFERENCES hackathons(id) ON DELETE CASCADE,minimum_age smallint,maximum_age smallint,student_required boolean,professional_allowed boolean,high_school_allowed boolean,undergraduate_allowed boolean,graduate_allowed boolean,individual_allowed boolean,team_required boolean,minimum_team_size smallint,maximum_team_size smallint,prior_project_allowed boolean,new_project_required boolean,residency_requirements text,citizenship_requirements text,experience_requirements text,employee_exclusions text,organization_exclusions text,eligibility_raw_text text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK (minimum_age IS NULL OR minimum_age >= 0),CHECK (maximum_age IS NULL OR maximum_age >= minimum_age),CHECK (minimum_team_size IS NULL OR minimum_team_size >= 1),CHECK (maximum_team_size IS NULL OR maximum_team_size >= minimum_team_size));
CREATE TABLE eligibility_countries (hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,country_code char(2) NOT NULL,allowed boolean NOT NULL,reason text,PRIMARY KEY(hackathon_id,country_code,allowed));
CREATE INDEX eligibility_country_lookup_idx ON eligibility_countries(country_code,allowed,hackathon_id);
CREATE TABLE event_phases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,name text NOT NULL,phase_type phase_type NOT NULL DEFAULT 'OTHER',starts_at timestamptz,ends_at timestamptz,format event_format,location_id uuid REFERENCES locations(id) ON DELETE SET NULL,description text,sort_order integer NOT NULL DEFAULT 0,CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at));
CREATE INDEX event_phases_event_order_idx ON event_phases(hackathon_id,sort_order);
CREATE TABLE prize_pools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,original_amount numeric(18,2),original_currency char(3),normalized_usd_amount numeric(18,2),fx_rate numeric(20,10),fx_rate_date date,estimated boolean NOT NULL DEFAULT false,non_cash boolean NOT NULL DEFAULT false,description text,observed_at timestamptz,CHECK (original_amount IS NULL OR original_amount >= 0),CHECK (normalized_usd_amount IS NULL OR normalized_usd_amount >= 0));
CREATE INDEX prize_pools_event_amount_idx ON prize_pools(hackathon_id,normalized_usd_amount DESC NULLS LAST);
CREATE TABLE prizes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,prize_pool_id uuid REFERENCES prize_pools(id) ON DELETE SET NULL,track_id uuid REFERENCES tracks(id) ON DELETE SET NULL,title text NOT NULL,placement text,original_amount numeric(18,2),original_currency char(3),normalized_usd_amount numeric(18,2),estimated_value numeric(18,2),quantity integer,non_cash_description text,description text,CHECK (original_amount IS NULL OR original_amount >= 0),CHECK (quantity IS NULL OR quantity >= 1));
CREATE TABLE judging_criteria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,name text NOT NULL,description text,weight numeric(7,4),sort_order integer NOT NULL DEFAULT 0,CHECK (weight IS NULL OR weight BETWEEN 0 AND 100));
CREATE TABLE requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,requirement_type requirement_type NOT NULL,name text,description text NOT NULL,required boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE event_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,resource_type resource_type NOT NULL,name text NOT NULL,description text,url text,provider_organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE external_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,link_type text NOT NULL,url text NOT NULL,normalized_url text NOT NULL,is_official boolean,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),UNIQUE(hackathon_id,normalized_url));
CREATE INDEX external_links_normalized_url_idx ON external_links(normalized_url);
CREATE TABLE participant_metric_observations (id bigserial PRIMARY KEY,hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,metric_type text NOT NULL CHECK (metric_type IN ('registrations','participants','teams','submissions','projects')),value bigint NOT NULL CHECK (value >= 0),observed_at timestamptz NOT NULL,source_observation_id bigint,UNIQUE(hackathon_id,metric_type,observed_at));
CREATE INDEX participant_metric_event_type_time_idx ON participant_metric_observations(hackathon_id,metric_type,observed_at DESC);
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,name text NOT NULL,description text,team_name text,repository_url text,demo_url text,video_url text,project_url text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX projects_hackathon_idx ON projects(hackathon_id);
CREATE TABLE project_technologies (project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,technology_id uuid NOT NULL REFERENCES technologies(id) ON DELETE CASCADE,PRIMARY KEY(project_id,technology_id));
CREATE TABLE awards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,project_id uuid REFERENCES projects(id) ON DELETE SET NULL,prize_id uuid REFERENCES prizes(id) ON DELETE SET NULL,title text NOT NULL,placement text,description text);

CREATE TABLE sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,domain citext,source_family text,source_type text,country_scope text[],language_scope text[],ingestion_mode source_ingestion_mode NOT NULL,discovery_enabled boolean NOT NULL DEFAULT true,detail_extraction_enabled boolean NOT NULL DEFAULT true,robots_status text,tos_status text,permission_status text,priority smallint NOT NULL DEFAULT 50 CHECK (priority BETWEEN 0 AND 100),trust_score numeric(5,4) CHECK (trust_score IS NULL OR trust_score BETWEEN 0 AND 1),refresh_interval_seconds integer,rate_limit_per_minute numeric(10,3),concurrency_limit smallint,parser_version text,extractor_version text,health source_health NOT NULL DEFAULT 'UNKNOWN',last_attempt_at timestamptz,last_success_at timestamptz,last_error_at timestamptz,active boolean NOT NULL DEFAULT true,notes text,config jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(domain,source_family));
CREATE INDEX sources_active_priority_idx ON sources(active,priority DESC);
CREATE INDEX sources_health_idx ON sources(health,last_success_at);
CREATE TABLE crawl_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE,status crawl_run_status NOT NULL DEFAULT 'RUNNING',started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,discovered_count integer NOT NULL DEFAULT 0,fetched_count integer NOT NULL DEFAULT 0,unchanged_count integer NOT NULL DEFAULT 0,changed_count integer NOT NULL DEFAULT 0,parsed_count integer NOT NULL DEFAULT 0,failed_count integer NOT NULL DEFAULT 0,valid_event_count integer NOT NULL DEFAULT 0,unique_event_count integer NOT NULL DEFAULT 0,error_summary text,stats jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX crawl_runs_source_time_idx ON crawl_runs(source_id,started_at DESC);
CREATE TABLE url_frontier (id bigserial PRIMARY KEY,source_id uuid REFERENCES sources(id) ON DELETE SET NULL,discovered_by_source_id uuid REFERENCES sources(id) ON DELETE SET NULL,discovery_query text,url text NOT NULL,canonical_url text NOT NULL,domain citext NOT NULL,state frontier_state NOT NULL DEFAULT 'DISCOVERED',priority integer NOT NULL DEFAULT 0,depth smallint NOT NULL DEFAULT 0,discovered_at timestamptz NOT NULL DEFAULT now(),next_fetch_at timestamptz,last_fetch_at timestamptz,retry_count integer NOT NULL DEFAULT 0,terminal_reason text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(canonical_url));
CREATE INDEX url_frontier_schedule_idx ON url_frontier(state,next_fetch_at,priority DESC);
CREATE INDEX url_frontier_domain_idx ON url_frontier(domain,state);
CREATE TABLE fetch_attempts (id bigserial PRIMARY KEY,frontier_id bigint REFERENCES url_frontier(id) ON DELETE SET NULL,crawl_run_id uuid REFERENCES crawl_runs(id) ON DELETE SET NULL,source_id uuid REFERENCES sources(id) ON DELETE SET NULL,requested_url text NOT NULL,final_url text,status fetch_status NOT NULL,http_status integer,content_type text,etag text,last_modified text,fetch_method text NOT NULL DEFAULT 'HTTP',started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,elapsed_ms integer,error_category text,error_message text,response_headers jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX fetch_attempts_source_time_idx ON fetch_attempts(source_id,started_at DESC);
CREATE INDEX fetch_attempts_frontier_time_idx ON fetch_attempts(frontier_id,started_at DESC);
CREATE TABLE raw_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid REFERENCES sources(id) ON DELETE SET NULL,fetch_attempt_id bigint REFERENCES fetch_attempts(id) ON DELETE SET NULL,url text NOT NULL,canonical_url text NOT NULL,http_status integer,content_type text,content_hash char(64) NOT NULL,normalized_text_hash char(64),object_storage_key text,extracted_text text,structured_data jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,fetched_at timestamptz NOT NULL,published_at timestamptz,parser_status text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(canonical_url,content_hash));
CREATE INDEX raw_documents_url_time_idx ON raw_documents(canonical_url,fetched_at DESC);
CREATE INDEX raw_documents_source_time_idx ON raw_documents(source_id,fetched_at DESC);
CREATE INDEX raw_documents_hash_idx ON raw_documents(content_hash);
CREATE TABLE source_event_refs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid REFERENCES sources(id) ON DELETE SET NULL,hackathon_id uuid REFERENCES hackathons(id) ON DELETE SET NULL,raw_document_id uuid REFERENCES raw_documents(id) ON DELETE SET NULL,source_event_id text,url text NOT NULL,normalized_url text NOT NULL,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),active boolean NOT NULL DEFAULT true,UNIQUE(source_id,normalized_url));
CREATE INDEX source_event_refs_hackathon_idx ON source_event_refs(hackathon_id);
CREATE INDEX source_event_refs_source_event_id_idx ON source_event_refs(source_id,source_event_id) WHERE source_event_id IS NOT NULL;

CREATE TABLE extraction_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),raw_document_id uuid NOT NULL REFERENCES raw_documents(id) ON DELETE CASCADE,extractor_version text NOT NULL,parser_version text,model_name text,prompt_version text,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,succeeded boolean,error_message text,metrics jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX extraction_runs_document_time_idx ON extraction_runs(raw_document_id,started_at DESC);
CREATE TABLE source_observations (id bigserial PRIMARY KEY,hackathon_id uuid REFERENCES hackathons(id) ON DELETE CASCADE,source_event_ref_id uuid REFERENCES source_event_refs(id) ON DELETE SET NULL,source_id uuid REFERENCES sources(id) ON DELETE SET NULL,raw_document_id uuid REFERENCES raw_documents(id) ON DELETE SET NULL,extraction_run_id uuid REFERENCES extraction_runs(id) ON DELETE SET NULL,field_path text NOT NULL,value_json jsonb NOT NULL,normalized_value_json jsonb,extraction_method extraction_method NOT NULL,extraction_confidence numeric(5,4),evidence_text text,evidence_locator text,derived boolean NOT NULL DEFAULT false,method_version text,observed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK (extraction_confidence IS NULL OR extraction_confidence BETWEEN 0 AND 1));
CREATE INDEX source_observations_event_field_time_idx ON source_observations(hackathon_id,field_path,observed_at DESC);
CREATE INDEX source_observations_source_time_idx ON source_observations(source_id,observed_at DESC);
CREATE INDEX source_observations_raw_document_idx ON source_observations(raw_document_id);
CREATE INDEX source_observations_value_gin_idx ON source_observations USING gin(normalized_value_json jsonb_path_ops);
ALTER TABLE participant_metric_observations ADD CONSTRAINT participant_metric_source_observation_fk FOREIGN KEY(source_observation_id) REFERENCES source_observations(id) ON DELETE SET NULL;
CREATE TABLE canonical_field_selections (id bigserial PRIMARY KEY,hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,field_path text NOT NULL,selected_observation_id bigint NOT NULL REFERENCES source_observations(id) ON DELETE RESTRICT,policy_version text NOT NULL,score numeric(8,6),selected_at timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX canonical_field_one_active_idx ON canonical_field_selections(hackathon_id,field_path) WHERE active;
CREATE INDEX canonical_field_observation_idx ON canonical_field_selections(selected_observation_id);
CREATE TABLE field_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,field_path text NOT NULL,severity conflict_severity NOT NULL,state review_state NOT NULL DEFAULT 'OPEN',observation_ids bigint[] NOT NULL,detected_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,resolution_note text,resolved_by_user_id uuid,CHECK (cardinality(observation_ids) >= 2));
CREATE INDEX field_conflicts_open_idx ON field_conflicts(state,severity,detected_at DESC);
CREATE INDEX field_conflicts_event_idx ON field_conflicts(hackathon_id,field_path);
CREATE TABLE canonical_changes (id bigserial PRIMARY KEY,hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,field_path text NOT NULL,change_type text NOT NULL,previous_selection_id bigint REFERENCES canonical_field_selections(id) ON DELETE SET NULL,new_selection_id bigint REFERENCES canonical_field_selections(id) ON DELETE SET NULL,old_value_json jsonb,new_value_json jsonb,meaningful boolean NOT NULL DEFAULT true,detected_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX canonical_changes_event_time_idx ON canonical_changes(hackathon_id,detected_at DESC);
CREATE INDEX canonical_changes_meaningful_time_idx ON canonical_changes(meaningful,detected_at DESC);

CREATE TABLE dedup_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),left_hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,right_hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,blocking_reason text NOT NULL,feature_json jsonb NOT NULL DEFAULT '{}'::jsonb,score numeric(8,6),model_version text,decision dedup_decision,review_state review_state NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,decided_by_user_id uuid,decision_reason text,CHECK (left_hackathon_id <> right_hackathon_id),CHECK (score IS NULL OR score BETWEEN 0 AND 1));
CREATE UNIQUE INDEX dedup_candidate_pair_unique_idx ON dedup_candidates(LEAST(left_hackathon_id,right_hackathon_id),GREATEST(left_hackathon_id,right_hackathon_id));
CREATE INDEX dedup_candidates_review_idx ON dedup_candidates(review_state,score DESC NULLS LAST);
CREATE TABLE hackathon_aliases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,alias_type text NOT NULL,alias_value text NOT NULL,normalized_alias text NOT NULL,source_id uuid REFERENCES sources(id) ON DELETE SET NULL,UNIQUE(alias_type,normalized_alias));
CREATE INDEX hackathon_aliases_event_idx ON hackathon_aliases(hackathon_id);
CREATE TABLE merge_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),survivor_hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE RESTRICT,retired_hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE RESTRICT,reason text NOT NULL,decision_source text NOT NULL,model_version text,actor_user_id uuid,created_at timestamptz NOT NULL DEFAULT now(),reversed_at timestamptz,reversal_note text,CHECK (survivor_hackathon_id <> retired_hackathon_id));

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email citext,display_name text,timezone text,country_code char(2),locale varchar(16),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(email));
CREATE TABLE user_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider auth_provider NOT NULL,provider_subject text NOT NULL,provider_email citext,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_subject));
CREATE INDEX user_identities_user_idx ON user_identities(user_id);
CREATE TABLE user_preferences (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,preferred_formats event_format[],preferred_country_codes char(2)[],travel_country_codes char(2)[],student_status text,experience_level text,team_preference text,minimum_prize_usd numeric(18,2),available_from date,available_until date,hard_constraints jsonb NOT NULL DEFAULT '{}'::jsonb,soft_preferences jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now(),CHECK (minimum_prize_usd IS NULL OR minimum_prize_usd >= 0),CHECK (available_until IS NULL OR available_from IS NULL OR available_until >= available_from));
CREATE TABLE user_preferred_tracks (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,track_id uuid NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,weight numeric(5,4) NOT NULL DEFAULT 1 CHECK (weight BETWEEN 0 AND 1),PRIMARY KEY(user_id,track_id));
CREATE TABLE user_preferred_technologies (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,technology_id uuid NOT NULL REFERENCES technologies(id) ON DELETE CASCADE,weight numeric(5,4) NOT NULL DEFAULT 1 CHECK (weight BETWEEN 0 AND 1),PRIMARY KEY(user_id,technology_id));
CREATE TABLE user_hackathon_states (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,state user_event_state NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,hackathon_id));
CREATE INDEX user_hackathon_state_lookup_idx ON user_hackathon_states(user_id,state,updated_at DESC);
CREATE TABLE eligibility_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,result eligibility_result NOT NULL,rules_version text NOT NULL,rationale jsonb NOT NULL,event_snapshot_hash char(64) NOT NULL,user_snapshot_hash char(64) NOT NULL,evaluated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX eligibility_eval_user_event_time_idx ON eligibility_evaluations(user_id,hackathon_id,evaluated_at DESC);
CREATE TABLE recommendation_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,hackathon_id uuid NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE,eligibility_result eligibility_result NOT NULL,score numeric(7,4),model_version text NOT NULL,positive_reasons jsonb NOT NULL DEFAULT '[]'::jsonb,negative_reasons jsonb NOT NULL DEFAULT '[]'::jsonb,generated_at timestamptz NOT NULL DEFAULT now(),CHECK (score IS NULL OR score BETWEEN 0 AND 100));
CREATE INDEX recommendation_user_score_idx ON recommendation_scores(user_id,score DESC NULLS LAST,generated_at DESC);

CREATE TABLE saved_searches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,original_query text,filter_schema_version text NOT NULL,filters jsonb NOT NULL,notifications_enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX saved_searches_user_idx ON saved_searches(user_id,updated_at DESC);
CREATE INDEX saved_searches_filters_gin_idx ON saved_searches USING gin(filters jsonb_path_ops);
CREATE TABLE alert_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,saved_search_id uuid REFERENCES saved_searches(id) ON DELETE CASCADE,hackathon_id uuid REFERENCES hackathons(id) ON DELETE CASCADE,alert_type text NOT NULL,channels alert_channel[] NOT NULL DEFAULT ARRAY['IN_APP']::alert_channel[],enabled boolean NOT NULL DEFAULT true,settings jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),CHECK (saved_search_id IS NOT NULL OR hackathon_id IS NOT NULL));
CREATE INDEX alert_rules_user_enabled_idx ON alert_rules(user_id,enabled);
CREATE TABLE alert_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,alert_rule_id uuid REFERENCES alert_rules(id) ON DELETE SET NULL,hackathon_id uuid REFERENCES hackathons(id) ON DELETE CASCADE,canonical_change_id bigint REFERENCES canonical_changes(id) ON DELETE SET NULL,alert_type text NOT NULL,dedup_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,UNIQUE(user_id,dedup_key));
CREATE INDEX alert_events_user_time_idx ON alert_events(user_id,created_at DESC);
CREATE TABLE alert_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),alert_event_id uuid NOT NULL REFERENCES alert_events(id) ON DELETE CASCADE,channel alert_channel NOT NULL,status alert_delivery_status NOT NULL DEFAULT 'PENDING',provider_message_id text,attempt_count integer NOT NULL DEFAULT 0,last_attempt_at timestamptz,sent_at timestamptz,error_message text,UNIQUE(alert_event_id,channel));

CREATE TABLE admin_audit_log (id bigserial PRIMARY KEY,actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,reason text,before_json jsonb,after_json jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX admin_audit_entity_idx ON admin_audit_log(entity_type,entity_id,created_at DESC);
CREATE TABLE review_queue_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),queue_type text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,severity conflict_severity NOT NULL DEFAULT 'MEDIUM',state review_state NOT NULL DEFAULT 'OPEN',payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),assigned_to_user_id uuid REFERENCES users(id) ON DELETE SET NULL,resolved_at timestamptz,UNIQUE(queue_type,entity_type,entity_id,state));
CREATE INDEX review_queue_open_idx ON review_queue_items(state,severity,created_at);
CREATE TABLE quality_snapshots (id bigserial PRIMARY KEY,scope_type text NOT NULL,scope_id text,measured_at timestamptz NOT NULL DEFAULT now(),identity_score numeric(5,2),dates_score numeric(5,2),eligibility_score numeric(5,2),prize_score numeric(5,2),location_score numeric(5,2),sources_score numeric(5,2),freshness_score numeric(5,2),consistency_score numeric(5,2),overall_score numeric(5,2),metrics jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX quality_snapshots_scope_time_idx ON quality_snapshots(scope_type,scope_id,measured_at DESC);

CREATE TRIGGER trg_event_series_updated BEFORE UPDATE ON event_series FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_locations_updated BEFORE UPDATE ON locations FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_organizations_updated BEFORE UPDATE ON organizations FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_people_updated BEFORE UPDATE ON people FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_hackathons_updated BEFORE UPDATE ON hackathons FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_eligibility_updated BEFORE UPDATE ON eligibility_rules FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_sources_updated BEFORE UPDATE ON sources FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_users_updated BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_user_states_updated BEFORE UPDATE ON user_hackathon_states FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_saved_searches_updated BEFORE UPDATE ON saved_searches FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Late foreign keys to user table (declared after users exists).
ALTER TABLE field_conflicts ADD CONSTRAINT field_conflicts_resolved_by_user_fk FOREIGN KEY(resolved_by_user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE dedup_candidates ADD CONSTRAINT dedup_candidates_decided_by_user_fk FOREIGN KEY(decided_by_user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE merge_audit ADD CONSTRAINT merge_audit_actor_user_fk FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL;
